/* Physically-grounded film-emulation data for src/iop/filmemulation.c --
 * real digitized spectral sensitivities, H&D characteristic curves, and
 * fitted split-normal-CDF gamma-correction models, sourced from the PoLUT
 * project (https://github.com -- see that project's README.md for the full
 * darkroom/color-science rationale, data provenance, and citation trail;
 * not repeated here). Exported via PoLUT's export_darktable_module.py and
 * transcribed into these tables by a one-off generator script -- treat this
 * file as data, not something to hand-edit; regenerate it if the source
 * data changes.
 *
 * #include'd directly into filmemulation.c (not separately compiled),
 * following the same convention as external/cie_colorimetric_tables.c.
 */

typedef struct dt_film_curve_point_t
{
  float x; // log10(exposure) for H&D curves; wavelength (nm) for sensitivity/filter curves
  float y; // density for H&D curves; log10(sensitivity) or %transmission for sensitivity/filter curves
} dt_film_curve_point_t;

typedef struct dt_film_curve_t
{
  const dt_film_curve_point_t *pts;
  int n;
} dt_film_curve_t;

// Fitted asymmetric cumulative-Gaussian ("split-normal") H&D curve model
// (PoLUT's *_SPLITGAUSS_FIT) -- D(x) = d_lo + (d_hi-d_lo)*Phi((x-x0)/sigma),
// sigma = sigma_lo for x<x0, sigma_hi for x>=x0. Used by the live
// Jones-system-gamma correction (gamma/punchiness slider).
typedef struct dt_film_splitgauss_t
{
  float x0, d_lo, d_hi, sigma_lo, sigma_hi;
} dt_film_splitgauss_t;

// DIR-coupler (development-inhibitor-releasing coupler) inter-layer
// gammas for the camera film's own emulsion -- how much developed density
// in a donor layer releases inhibitor toward each receiver layer. Row is
// the donor, per Python's compute_dir_couplers_matrix() convention:
// gamma_samelayer_rgb is the diagonal (self-inhibition, local contrast);
// gamma_interlayer_x_to_yz are the two off-diagonal entries a donor layer
// x sends to the other two receivers y,z. Ported from spektrafilm's
// DirCouplersParams per-process/per-stock defaults -- see task 02's task
// file for the physical rationale and provenance.
typedef struct dt_film_dir_couplers_t
{
  float gamma_samelayer_rgb[3];
  float gamma_interlayer_r_to_gb[2];
  float gamma_interlayer_g_to_rb[2];
  float gamma_interlayer_b_to_rg[2];
} dt_film_dir_couplers_t;

typedef struct dt_film_reversal_t
{
  dt_film_curve_t sens[3];
  dt_film_curve_t curves[3];
  float ref_d[3];
  dt_film_splitgauss_t fit[3];
  dt_film_dir_couplers_t dir_couplers;
} dt_film_reversal_t;

typedef struct dt_film_negative_t
{
  dt_film_curve_t sens[3];
  dt_film_curve_t curves[3];
  float ref_d[3];
  dt_film_splitgauss_t fit[3];
  dt_film_dir_couplers_t dir_couplers;
} dt_film_negative_t;

typedef struct dt_film_paper_t
{
  dt_film_curve_t curves[3];
  dt_film_splitgauss_t fit[3];
} dt_film_paper_t;

